/**
 * Image bytes for the mock resource library.
 *
 * The library's image sections are drawn from the resource content endpoint
 * itself, there being no stored thumbnail for a resource, so a fixture library
 * whose content endpoint answers with a string renders a grid of broken tiles.
 *
 * They are drawings rather than colour swatches, and that is the point of them
 * rather than decoration. A resource opens at a page of its own (#1470) and is
 * referenced from an asset's sidebar (#1475), so these bytes are shown at full
 * width and as a thumbnail beside a file name. A 16x12 gradient scaled up to
 * fill a viewer reads as a broken image, and a fixture that reads as broken
 * makes every capture taken through it worthless. Each one draws what its
 * resource says it is, at 960x640 on an opaque background -- opaque because a
 * transparent fixture shows the viewer's checkerboard rather than an image.
 */
const PNG: Record<string, string> = {
  warehouse:
    "",
  rack:
    "",
  dock:
    "",
  pipeline:
    "",
  frontage:
    "",
  endcap:
    "",
};

// Which drawing stands in for which fixture. Two libraries hold images -- the
// data-engineer persona's and the signed-in reader's own -- so the drawings are
// named for what they depict rather than keyed by resource id.
const IMAGE_BY_RESOURCE: Record<string, string> = {
  "res-029": "warehouse",
  "res-030": "rack",
  "res-031": "dock",
  "res-032": "pipeline",
  "res-033": "frontage",
  "res-034": "endcap",
};

export function resourceImageBytes(id: string): Uint8Array | undefined {
  const key = IMAGE_BY_RESOURCE[id];
  const encoded = key ? PNG[key] : undefined;
  if (!encoded) return undefined;
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
